package dev.cnnnr;

import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * A party broadcast of the sender's current active path: parallel arrays of tile coordinates
 * and the number of ticks spent on each. An empty payload means the sender's path was cleared.
 */
@Value
@EqualsAndHashCode(callSuper = true)
public class PathUpdate extends PartyMemberMessage
{
	int[] xs;
	int[] ys;
	int[] planes;
	int[] ticks;
	int rgb;
}

package dev.cnnnr;

/**
 * How a finished path disappears once the player has been idle past the reset threshold.
 */
public enum ResetAnimation
{
	/** Reel the path in towards the tile the player stopped on. */
	RETRACT("Retract"),
	/** Fade the whole path out in place. */
	FADE("Fade"),
	/** Hold the path briefly, then clear it with no animation. */
	NONE("Instant");

	private final String label;

	ResetAnimation(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package dev.cnnnr;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.coords.WorldPoint;

/**
 * An ordered sequence of tiles the player occupied, oldest first and newest last.
 * Consecutive ticks spent on the same tile are collapsed into a single {@link PathTile}.
 */
class RecordedPath
{
	@Getter
	private final List<PathTile> tiles = new ArrayList<>();

	/**
	 * Wall-clock time (ms) the path was committed on an idle reset, used to drive the
	 * retract/fade animation. Zero while the path is still being actively recorded.
	 */
	@Getter
	@Setter
	private long committedAtMillis;

	void add(WorldPoint worldPoint)
	{
		tiles.add(new PathTile(worldPoint));
	}

	void add(WorldPoint worldPoint, int ticks)
	{
		tiles.add(new PathTile(worldPoint, ticks));
	}

	PathTile last()
	{
		return tiles.isEmpty() ? null : tiles.get(tiles.size() - 1);
	}

	boolean isEmpty()
	{
		return tiles.isEmpty();
	}

	int size()
	{
		return tiles.size();
	}
}

package dev.cnnnr;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;

@PluginDescriptor(
	name = "Path Timer",
	description = "Records your tile-by-tile movement with per-tile tick timings for practicing tick-perfect positioning",
	tags = {"tick", "pvm", "movement", "path", "timing", "positioning"}
)
public class PathTimerPlugin extends Plugin
{
	private static final int PARTY_BROADCAST_MAX = 128;
	private static final long REMOTE_STALE_MS = 2500;
	private static final String PARTY_CONFIG_GROUP = "party";
	private static final String PARTY_MEMBER_COLOR_KEY = "memberColor";

	@Inject
	private Client client;

	@Inject
	private PathTimerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PathTimerOverlay overlay;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private ConfigManager configManager;

	/** The path currently being recorded. */
	@Getter
	private RecordedPath active = new RecordedPath();

	/** The most recently finished path, animating out; null when nothing is being shown. */
	@Getter
	private RecordedPath committed;

	/** Paths received from other party members, keyed by their member id. */
	@Getter
	private final Map<Long, RemotePath> remotePaths = new ConcurrentHashMap<>();

	private WorldPoint lastTile;
	private WorldPoint anchor;
	private int idleTicks;
	private boolean recording;
	private int lastBroadcastSignature;

	@Override
	protected void startUp()
	{
		reset();
		wsClient.registerMessage(PathUpdate.class);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		wsClient.unregisterMessage(PathUpdate.class);
		reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				reset();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Drop the finished path once its retract/fade animation has run its course.
		if (committed != null
			&& System.currentTimeMillis() - committed.getCommittedAtMillis() >= config.resetAnimationMs())
		{
			committed = null;
		}

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		final WorldPoint tile = local.getWorldLocation();
		if (tile == null)
		{
			return;
		}

		// Movement is caught by the position delta; sustained combat/skilling by the
		// animation and interaction state (so a DPS phase on one tile is not treated as idle).
		final boolean moved = lastTile != null && !tile.equals(lastTile);
		final boolean animating = local.getAnimation() != -1;
		final boolean interacting = local.getInteracting() != null;
		final boolean activeThisTick = moved || animating || interacting;

		if (activeThisTick)
		{
			idleTicks = 0;

			if (!recording)
			{
				// Start a fresh path anchored on the tile we were resting on.
				recording = true;
				active = new RecordedPath();
				if (anchor != null)
				{
					active.add(anchor);
				}
			}

			recordTile(tile);
		}
		else
		{
			idleTicks++;

			if (recording)
			{
				// Keep growing the resting tile's tick count until we cross the idle threshold.
				recordTile(tile);

				if (idleTicks >= config.idleResetTicks())
				{
					commit();
					recording = false;
					anchor = tile;
				}
			}
			else
			{
				anchor = tile;
			}
		}

		lastTile = tile;

		syncParty();
	}

	@Subscribe
	public void onPathUpdate(PathUpdate event)
	{
		// Runs on the websocket thread; touch only plain data and the concurrent map here.
		final PartyMember localMember = partyService.getLocalMember();
		if (localMember != null && event.getMemberId() == localMember.getMemberId())
		{
			return; // our own broadcast echoed back
		}

		final int[] xs = event.getXs();
		final int[] ys = event.getYs();
		final int[] planes = event.getPlanes();
		final int[] ticks = event.getTicks();

		if (xs == null || ys == null || planes == null || ticks == null
			|| xs.length != ys.length || xs.length != planes.length || xs.length != ticks.length)
		{
			return; // malformed payload
		}

		if (xs.length == 0)
		{
			// Their path reset: animate out their last-known path instead of dropping it instantly.
			remotePaths.computeIfPresent(event.getMemberId(), (id, existing) ->
				existing.getCommittedAtMillis() == 0
					? new RemotePath(existing.getPath(), existing.getUpdatedAt(), existing.getRgb(), System.currentTimeMillis())
					: existing);
			return;
		}

		final RecordedPath path = new RecordedPath();
		for (int i = 0; i < xs.length; i++)
		{
			path.add(new WorldPoint(xs[i], ys[i], planes[i]), ticks[i]);
		}

		remotePaths.put(event.getMemberId(), new RemotePath(path, System.currentTimeMillis(), event.getRgb(), 0L));
	}

	private void syncParty()
	{
		if (config.showPartyPaths() && partyService.isInParty())
		{
			broadcastPath();
			expireRemotePaths();
		}
		else if (!remotePaths.isEmpty())
		{
			remotePaths.clear();
		}
	}

	private void expireRemotePaths()
	{
		final long now = System.currentTimeMillis();
		final int animMs = config.resetAnimationMs();

		for (final Map.Entry<Long, RemotePath> entry : remotePaths.entrySet())
		{
			final RemotePath remote = entry.getValue();
			if (remote.getCommittedAtMillis() != 0)
			{
				if (now - remote.getCommittedAtMillis() >= animMs)
				{
					remotePaths.remove(entry.getKey(), remote); // reset animation finished
				}
			}
			else if (now - remote.getUpdatedAt() > REMOTE_STALE_MS)
			{
				// Stopped broadcasting (e.g. logged out): animate their path out as well.
				entry.setValue(new RemotePath(remote.getPath(), remote.getUpdatedAt(), remote.getRgb(), now));
			}
		}
	}

	private void broadcastPath()
	{
		final int size = active.size();
		final int count = Math.min(size, PARTY_BROADCAST_MAX);
		final int start = size - count;

		final int[] xs = new int[count];
		final int[] ys = new int[count];
		final int[] planes = new int[count];
		final int[] ticks = new int[count];

		for (int i = 0; i < count; i++)
		{
			final PathTile tile = active.getTiles().get(start + i);
			final WorldPoint wp = tile.getWorldPoint();
			xs[i] = wp.getX();
			ys[i] = wp.getY();
			planes[i] = wp.getPlane();
			ticks[i] = tile.getTicks();
		}

		final int rgb = localPartyColor().getRGB();

		int signature = Arrays.hashCode(xs);
		signature = 31 * signature + Arrays.hashCode(ys);
		signature = 31 * signature + Arrays.hashCode(planes);
		signature = 31 * signature + Arrays.hashCode(ticks);
		signature = 31 * signature + rgb;

		if (signature == lastBroadcastSignature)
		{
			return; // unchanged since our last broadcast
		}
		lastBroadcastSignature = signature;

		partyService.send(new PathUpdate(xs, ys, planes, ticks, rgb));
	}

	private void recordTile(WorldPoint tile)
	{
		final PathTile last = active.last();
		if (last != null && last.getWorldPoint().equals(tile))
		{
			last.incrementTicks();
			return;
		}

		active.add(tile);

		final int max = config.maxTiles();
		while (active.size() > max)
		{
			active.getTiles().remove(0);
		}
	}

	private void commit()
	{
		if (active.isEmpty())
		{
			return;
		}

		active.setCommittedAtMillis(System.currentTimeMillis());
		committed = active;
		active = new RecordedPath();
	}

	private void reset()
	{
		active = new RecordedPath();
		committed = null;
		lastTile = null;
		anchor = null;
		idleTicks = 0;
		recording = false;
		lastBroadcastSignature = 0;
		remotePaths.clear();
	}

	/** Whether party colouring is currently in effect (enabled and in a party). */
	boolean isPartyActive()
	{
		return config.showPartyPaths() && partyService.isInParty();
	}

	/** Colour to draw the local player's own path in. */
	Color localDisplayColor()
	{
		return isPartyActive() ? localPartyColor() : config.pathColor();
	}

	/** The local player's current party colour, matching the Party plugin (custom colour, else name-derived). */
	private Color localPartyColor()
	{
		final Color configured = configManager.getConfiguration(PARTY_CONFIG_GROUP, PARTY_MEMBER_COLOR_KEY, Color.class);
		if (configured != null)
		{
			return configured;
		}

		final PartyMember local = partyService.getLocalMember();
		if (local != null)
		{
			return ColorUtil.fromObject(local.getDisplayName());
		}

		return config.pathColor();
	}

	@Provides
	PathTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PathTimerConfig.class);
	}
}

package dev.cnnnr;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(PathTimerConfig.GROUP)
public interface PathTimerConfig extends Config
{
	String GROUP = "pathtimer";

	@ConfigItem(
		keyName = "idleResetTicks",
		name = "Idle reset (ticks)",
		description = "Retract the recorded path once you have been fully idle (not moving, animating or interacting) for this many ticks.",
		position = 0
	)
	@Range(min = 1, max = 50)
	default int idleResetTicks()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "resetAnimation",
		name = "Reset animation",
		description = "How the finished path disappears after an idle reset.",
		position = 1
	)
	default ResetAnimation resetAnimation()
	{
		return ResetAnimation.RETRACT;
	}

	@ConfigItem(
		keyName = "resetAnimationMs",
		name = "Animation length (ms)",
		description = "How long the retract or fade of a finished path lasts, and how long it stays on screen for review.",
		position = 2
	)
	@Range(min = 0, max = 5000)
	default int resetAnimationMs()
	{
		return 800;
	}

	@ConfigItem(
		keyName = "showTicks",
		name = "Show tick counts",
		description = "Draw how many ticks were spent on each tile.",
		position = 3
	)
	default boolean showTicks()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showStartTile",
		name = "Show start tile",
		description = "Include the first tile (where the recording starts) in the drawn path.",
		position = 4
	)
	default boolean showStartTile()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showStartTick",
		name = "Show start tile count",
		description = "Draw the tick count on the start tile. Its count marks the start rather than measuring a pause.",
		position = 5
	)
	default boolean showStartTick()
	{
		return false;
	}

	@ConfigItem(
		keyName = "connectTiles",
		name = "Connect tiles",
		description = "Draw a line through the tiles in the order they were visited.",
		position = 6
	)
	default boolean connectTiles()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "tileFillColor",
		name = "Tile fill colour",
		description = "Fill colour for each path tile; fully transparent means no fill. Outside a party this colour is used directly. In a party only its transparency is kept and the colour is taken from the party member.",
		position = 7
	)
	default Color tileFillColor()
	{
		return new Color(255, 255, 0, 0);
	}

	@Alpha
	@ConfigItem(
		keyName = "tileBorderColor",
		name = "Tile border colour",
		description = "Border colour for each path tile; fully transparent means no border. Outside a party this colour is used directly. In a party only its transparency is kept and the colour is taken from the party member.",
		position = 8
	)
	default Color tileBorderColor()
	{
		return new Color(255, 255, 0, 128);
	}

	@Alpha
	@ConfigItem(
		keyName = "pathColor",
		name = "Path colour",
		description = "Colour of the path line and tick counts.",
		position = 9
	)
	default Color pathColor()
	{
		return Color.YELLOW;
	}

	@ConfigItem(
		keyName = "lineWidth",
		name = "Line width",
		description = "Thickness of the path line.",
		position = 10
	)
	@Range(min = 1, max = 8)
	default int lineWidth()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "maxTiles",
		name = "Max tiles",
		description = "Safety cap on how many tiles a single path may contain before the oldest are dropped.",
		position = 11
	)
	@Range(min = 8, max = 1024)
	default int maxTiles()
	{
		return 256;
	}

	@ConfigItem(
		keyName = "showPartyPaths",
		name = "Show party member paths",
		description = "While in a party, colour your path with your party colour and draw other party members' paths in theirs. "
			+ "Other members must also run this plugin, and their path only shows while they are near you. "
			+ "Broadcasts your tile path to your party via the RuneLite party server.",
		position = 12
	)
	default boolean showPartyPaths()
	{
		return true;
	}
}

package dev.cnnnr;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * A single tile the player occupied for one or more consecutive game ticks.
 */
@Getter
class PathTile
{
	private final WorldPoint worldPoint;
	private int ticks;

	PathTile(WorldPoint worldPoint)
	{
		this.worldPoint = worldPoint;
		this.ticks = 1;
	}

	PathTile(WorldPoint worldPoint, int ticks)
	{
		this.worldPoint = worldPoint;
		this.ticks = ticks;
	}

	void incrementTicks()
	{
		ticks++;
	}
}

package dev.cnnnr;

import lombok.Value;

/** A party member's most recently received path, with the time it arrived (for staleness). */
@Value
class RemotePath
{
	RecordedPath path;
	long updatedAt;
	int rgb;
	/** When the sender's path reset and began animating out; 0 while it is still live. */
	long committedAtMillis;
}

package dev.cnnnr;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class PathTimerOverlay extends Overlay
{
	private final Client client;
	private final PathTimerPlugin plugin;
	private final PathTimerConfig config;

	@Inject
	PathTimerOverlay(Client client, PathTimerPlugin plugin, PathTimerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Shared across every path this frame so labels from different members on the same tile stack instead of overlapping.
		final Map<WorldPoint, Integer> labelStacks = new HashMap<>();

		// Draw other party members' paths first so the local player's own path always sits on top.
		if (config.showPartyPaths())
		{
			for (final RemotePath remote : plugin.getRemotePaths().values())
			{
				final Color color = new Color(remote.getRgb(), true);
				if (remote.getCommittedAtMillis() != 0)
				{
					// The member reset (empty broadcast) or stopped broadcasting: animate out on their timing.
					drawResetAnimation(graphics, remote.getPath(), remote.getCommittedAtMillis(), color, true, labelStacks);
				}
				else
				{
					drawPath(graphics, remote.getPath(), 0.0, 1.0f, color, true, labelStacks);
				}
			}
		}

		final boolean localParty = plugin.isPartyActive();
		final Color localColor = plugin.localDisplayColor();

		final RecordedPath committed = plugin.getCommitted();
		if (committed != null && !committed.isEmpty())
		{
			drawResetAnimation(graphics, committed, committed.getCommittedAtMillis(), localColor, localParty, labelStacks);
		}

		final RecordedPath active = plugin.getActive();
		if (active != null && !active.isEmpty())
		{
			drawPath(graphics, active, 0.0, 1.0f, localColor, localParty, labelStacks);
		}

		return null;
	}

	private void drawResetAnimation(Graphics2D graphics, RecordedPath path, long committedAtMillis, Color color,
		boolean partyColored, Map<WorldPoint, Integer> labelStacks)
	{
		final int duration = config.resetAnimationMs();
		final double progress = duration <= 0
			? 1.0
			: Math.min(1.0, (double) (System.currentTimeMillis() - committedAtMillis) / duration);

		switch (config.resetAnimation())
		{
			case RETRACT:
				drawPath(graphics, path, progress, 1.0f, color, partyColored, labelStacks);
				break;
			case FADE:
				drawPath(graphics, path, 0.0, (float) (1.0 - progress), color, partyColored, labelStacks);
				break;
			case NONE:
			default:
				drawPath(graphics, path, 0.0, 1.0f, color, partyColored, labelStacks);
				break;
		}
	}

	/**
	 * @param removeFraction fraction of the path length, measured from the start, to hide (drives the retract animation)
	 * @param alpha          overall opacity multiplier (drives the fade animation)
	 * @param baseColor      colour to draw the path and its counts in
	 */
	private void drawPath(Graphics2D graphics, RecordedPath path, double removeFraction, float alpha, Color baseColor,
		boolean partyColored, Map<WorldPoint, Integer> labelStacks)
	{
		final List<PathTile> tiles = path.getTiles();
		final int n = tiles.size();
		if (n == 0)
		{
			return;
		}
		final int first = config.showStartTile() ? 0 : 1;

		// Project each tile to the canvas once. Tiles outside the loaded scene project to null.
		final LocalPoint[] locals = new LocalPoint[n];
		final Point[] canvas = new Point[n];
		final double[] cumulative = new double[n];

		for (int i = 0; i < n; i++)
		{
			final WorldPoint wp = tiles.get(i).getWorldPoint();
			final LocalPoint lp = LocalPoint.fromWorld(client, wp);
			locals[i] = lp;
			canvas[i] = lp == null ? null : Perspective.localToCanvas(client, lp, wp.getPlane());

			if (i > first)
			{
				final WorldPoint prev = tiles.get(i - 1).getWorldPoint();
				cumulative[i] = cumulative[i - 1] + Math.hypot(wp.getX() - prev.getX(), wp.getY() - prev.getY());
			}
		}

		final double removeLength = removeFraction * cumulative[n - 1];
		final Color lineColor = withAlpha(baseColor, alpha);
		final Color fillColor = tileColor(config.tileFillColor(), baseColor, partyColored);
		final Color borderColor = tileColor(config.tileBorderColor(), baseColor, partyColored);
		final boolean drawFill = fillColor.getAlpha() > 0;
		final boolean drawBorder = borderColor.getAlpha() > 0;

		if (config.connectTiles())
		{
			graphics.setColor(lineColor);
			final Stroke previousStroke = graphics.getStroke();
			graphics.setStroke(new BasicStroke(config.lineWidth()));

			for (int i = first; i < n - 1; i++)
			{
				if (cumulative[i + 1] <= removeLength)
				{
					continue; // segment already fully reeled in
				}

				Point a = canvas[i];
				final Point b = canvas[i + 1];
				if (a == null || b == null)
				{
					continue; // segment leaves the loaded scene
				}

				if (cumulative[i] < removeLength)
				{
					// Partially reeled in: begin the line at the interpolated cut point.
					final double segment = cumulative[i + 1] - cumulative[i];
					final double f = segment <= 0 ? 0 : (removeLength - cumulative[i]) / segment;
					a = lerp(a, b, f);
				}

				graphics.drawLine(a.getX(), a.getY(), b.getX(), b.getY());
			}

			graphics.setStroke(previousStroke);
		}

		// Merge the tick counts of tiles visited more than once into a single "1, 2" label
		// (oldest visit first) so repeat visits don't stack labels on the same spot.
		final Map<WorldPoint, StringBuilder> labels = new LinkedHashMap<>();
		final Map<WorldPoint, LocalPoint> labelLocations = new HashMap<>();
		final Set<WorldPoint> filled = new HashSet<>();

		for (int i = first; i < n; i++)
		{
			if (cumulative[i] < removeLength || canvas[i] == null)
			{
				continue; // tile has been reeled in, or is off-scene
			}

			final WorldPoint wp = tiles.get(i).getWorldPoint();

			if ((drawFill || drawBorder) && filled.add(wp))
			{
				final Polygon poly = Perspective.getCanvasTilePoly(client, locals[i]);
				if (poly != null)
				{
					if (drawFill)
					{
						graphics.setColor(withAlpha(fillColor, alpha));
						graphics.fill(poly);
					}
					if (drawBorder)
					{
						graphics.setColor(withAlpha(borderColor, alpha));
						graphics.draw(poly);
					}
				}
			}

			// The start tile's count is a start marker, not a measured dwell, so it can be hidden on its own.
			if (config.showTicks() && (i != 0 || config.showStartTick()))
			{
				StringBuilder label = labels.get(wp);
				if (label == null)
				{
					label = new StringBuilder();
					labels.put(wp, label);
					labelLocations.put(wp, locals[i]);
				}
				else
				{
					label.append(", ");
				}
				label.append(tiles.get(i).getTicks());
			}
		}

		if (config.showTicks())
		{
			final int lineHeight = graphics.getFontMetrics().getHeight();
			for (final Map.Entry<WorldPoint, StringBuilder> entry : labels.entrySet())
			{
				final WorldPoint wp = entry.getKey();
				final String text = entry.getValue().toString();
				final Point base = Perspective.getCanvasTextLocation(client, graphics, labelLocations.get(wp), text, 0);
				if (base == null)
				{
					continue;
				}

				// Stack labels from different paths that land on the same tile so they don't overlap.
				final int level = labelStacks.merge(wp, 1, Integer::sum) - 1;
				final Point textLocation = new Point(base.getX(), base.getY() - level * lineHeight);
				OverlayUtil.renderTextLocation(graphics, textLocation, text, lineColor);
			}
		}
	}

	private static Point lerp(Point a, Point b, double f)
	{
		return new Point(
			(int) Math.round(a.getX() + (b.getX() - a.getX()) * f),
			(int) Math.round(a.getY() + (b.getY() - a.getY()) * f));
	}

	private static Color tileColor(Color configured, Color partyBase, boolean partyColored)
	{
		if (!partyColored)
		{
			return configured;
		}
		// In a party, keep only the configured transparency; take the colour from the party member.
		return new Color(partyBase.getRed(), partyBase.getGreen(), partyBase.getBlue(), configured.getAlpha());
	}

	private static Color withAlpha(Color color, float alpha)
	{
		final float clamped = Math.max(0f, Math.min(1f, alpha));
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.round(clamped * color.getAlpha()));
	}
}
